function addJourneyTasks(){for(const t of journeyTasks)if(!state.tasks.some(x=>x.id===t.id))state.tasks.push({...t});if(!state.journeyPrefs.briefNov11){Object.assign(state.journeyPrefs,{career:'Industry job',region:'Open to multi-country funding',family:'500000',loan:'Undecided',briefNov11:true})}}
const upgradeBeforeJourney=ensureUpgrade;ensureUpgrade=function(){upgradeBeforeJourney();addJourneyTasks()};ensureUpgrade();save();
const backupBeforeJourney=upgradeBackup;upgradeBackup=function(d){const out=backupBeforeJourney(d);if(d.journeyPrefs){if(typeof d.journeyPrefs!=='object'||!['career','region','family','loan'].every(k=>typeof d.journeyPrefs[k]==='string'))throw Error();out.journeyPrefs=d.journeyPrefs}return out};
const viewOrder={overview:views.overview,weekly:views.weekly,journey:'Full journey',...views};Object.keys(views).forEach(k=>delete views[k]);Object.assign(views,viewOrder);icons.journey=icons.timeline;
const briefBeforeJourney=overview;overview=function(){return briefBeforeJourney().replaceAll(' / 5',' / '+universities.length).replace('Researched tuition-free options','Research + applied programme options').replace('5 options',universities.length+' options').replace('A checked prerequisite matrix','A checked prerequisite matrix')+`<section class="panel" style="margin-top:18px"><h3>Your full journey, with dependencies</h3><p>Research universities and applied-sciences routes are both included. Passport → evidence → eligibility → exams / APS → applications → funding → visa → arrival → study and career.</p><a href="#journey">Open your full journey plan</a></section>`};
function typeGuide(){return `<div class="grid"><section class="panel"><span class="pill">Universität / TU</span><h3>Research universities</h3><p>Often place more emphasis on theoretical foundations, methods and basic research. Good routes to research-intensive study, and also to industry careers.</p><small>Your original five options are in this category.</small></section><section class="panel"><span class="pill">HAW / FH</span><h3>Universities of applied sciences</h3><p>Often emphasise application-based research, projects and industry collaboration. They can also support later PhD applications; check the actual curriculum and supervision.</p><small>Fulda, HAW Kiel, H-BRS and TH Ingolstadt are in this category.</small></section></div><p class="muted" style="font-size:12px">The institution type is not an admission difficulty or quality ranking. Both can lead to industry or research. ${link('https://static.daad.de/media/daad_de/pdfs_nicht_barrierefrei/in-deutschland-studieren-forschen-lehren/daad_hs_brosch%C3%BCre_en_web_rz.pdf','DAAD’s higher-education guide')}</p>`}
unis=function(){return heading('Two routes. One informed shortlist.','Explore research universities and universities of applied sciences separately, with city, fees and admission checks.')+typeGuide()+`<div class="notice"><b>Cost comparison:</b> “Programme-length” uses the published shortest route, while “24-month” compares a common period. Costs include assumed living, tuition and semester fees only. Applications, exams, deposits and setup are extra. Fulda may require 24 months; credit equivalence is unassessed. Research-programme semester figures remain planning provisions.</div><div class="toolbar"><input id="uni-search" placeholder="Search university, city, subject or requirement" aria-label="Search universities"><select id="uni-filter" aria-label="Filter universities"><option value="all">All programmes</option><option value="saved">My shortlist</option></select><select id="uni-type" aria-label="Institution type"><option value="all">Both institution types</option><option>Research university</option><option>University of applied sciences</option></select><select id="uni-fees" aria-label="Tuition filter"><option value="zero">Zero tuition only</option><option value="all">Include paid-fee comparison</option></select><select id="uni-sort" aria-label="Cost comparison period"><option value="24">Sort by 24-month estimate</option><option value="actual">Sort by programme-length estimate</option></select></div><p id="uni-count" class="muted"></p><div id="uni-results"></div>`};
function universityEstimate(u,months){return (months*u.monthly+Math.ceil(months/6)*(u.semester+u.tuition))*state.budget.rate}
uniResults=function(){const q=($('#uni-search')?.value||'').toLowerCase(),only=$('#uni-filter')?.value==='saved',type=$('#uni-type')?.value||'all',paid=$('#uni-fees')?.value==='all',actual=$('#uni-sort')?.value==='actual';const result=universities.filter(u=>(!only||state.shortlist.includes(u.id))&&(type==='all'||u.type===type)&&(paid||u.tuition===0)&&JSON.stringify(u).toLowerCase().includes(q)).sort((a,b)=>universityEstimate(a,actual?a.months:24)-universityEstimate(b,actual?b.months:24));if($('#uni-count'))$('#uni-count').textContent=result.length+' programmes shown · eligibility still needs transcript assessment';$('#uni-results').innerHTML=result.map((u,i)=>`<article class="uni"><div class="uni-top"><div class="rank">${i+1}</div><div class="uni-heading"><h3>${u.name}</h3><div>${u.course}</div><p class="muted" style="font-size:13px;margin:6px 0">${u.city}${u.state?', '+u.state:''}</p></div><div class="cost">${money(universityEstimate(u,actual?u.months:24))}<small>${actual?u.months+'-month route':'24-month comparison'} · estimated</small></div></div><div class="uni-meta"><span class="pill">${u.type}</span><span class="${u.tuition?'pill':'tag'}">${u.tuition?'€'+u.tuition+' tuition / semester':'₹0 tuition currently'}</span><span class="pill">${u.intake}</span><span class="pill">${u.durationLabel||u.months+' months'}</span></div><p>${u.fit}</p><p class="muted" style="font-size:12px">Shortest-route estimate: ${money(universityEstimate(u,u.months))}; common 24-month comparison: ${money(universityEstimate(u,24))}. Programme duration / eligibility must be confirmed.</p><button data-shortlist="${u.id}" class="${state.shortlist.includes(u.id)?'primary':''}">${state.shortlist.includes(u.id)?'Shortlisted ✓':'Add to shortlist'}</button> <button data-use-budget="${u.id}">Use in budget</button><details><summary>Admission, deadlines and cost evidence</summary><p><b>Requirements:</b> ${u.requirements}</p><p><b>Deadline:</b> ${u.deadline}</p><p><b>Fees:</b> ${u.feeStatus}</p><p><b>Planning:</b> €${u.monthly}/month living, €${u.semester}/semester contribution. ${u.months}-month shortest route used for programme-length estimate. City assumptions are not guaranteed quotes.</p><p><b>Watch carefully:</b> ${u.risk}</p><small>Checked ${u.checked}. Future rules and fees can change.</small><div class="links">${link(u.url,'Official programme / admission')}${link(u.costSource,'Cost evidence')}</div></details></article>`).join('')||'<p class="empty">No programmes match. Change type, tuition filter or search.</p>'};
const comparisonBeforeJourney=compare;compare=function(){return comparisonBeforeJourney().replace('<tbody>','<tbody><tr><td>City & institution type</td>'+universities.map(u=>`<td><b>${u.city}</b><p>${u.type}</p><small>${u.durationLabel||u.months+' months'}</small></td>`).join('')+'</tr>').replaceAll('<span class="tag">₹0 listed</span>', '<span class="tag">Check individual tuition below</span>')+`<div class="panel" style="margin-top:18px"><h3>Fee and subject-fit distinctions</h3><p>TH Ingolstadt’s listed AI programme charges €1,200 tuition per semester for affected non-EU applicants. All other listed routes currently show no general tuition. Fulda requires A2 German; HAW Kiel requires GRE for degrees outside the Bologna area. H-BRS is robotics/autonomy rather than a general Data Science master’s.</p></div>`};
function journey(){const p=state.journeyPrefs;return heading('The whole journey, one phase at a time.','A working plan for winter 2027/28, with summer 2028 as a separate fallback. Suggested work periods are not official deadlines.')+`<section class="panel"><h3>Decisions that shape your plan</h3><p class="panel-subtitle">Keep these undecided until you are ready. Nothing here changes a submitted application.</p><div class="fields"><label>Career direction<select data-journey-pref="career">${['Undecided','Industry job','Research / PhD','Keep both open'].map(v=>`<option ${p.career===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Study location<select data-journey-pref="region">${['Undecided','Germany only','Open to multi-country funding'].map(v=>`<option ${p.region===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Family upfront ceiling in INR<input type="text" data-journey-pref="family" value="${esc(p.family)}" placeholder="Not decided yet"></label><label>Repayable support<select data-journey-pref="loan">${['Undecided','Avoid loans','Only as backup','Open to loans'].map(v=>`<option ${p.loan===v?'selected':''}>${v}</option>`).join('')}</select></label></div></section><div class="notice"><b>Early decision:</b> H-BRS’s international application window for winter 2027/28 ends 15 February 2027 on its current admissions page. For summer 2028, its reference deadline is 15 August 2027. Your semester 7 / APS readiness must be checked against these dates. Fulda Data Science has no summer intake.</div>${journeyPhases.map((phase,i)=>{const ts=phase.tasks.map(id=>state.tasks.find(t=>t.id===id)).filter(Boolean),done=ts.filter(t=>t.done).length;return `<section class="panel" style="margin-top:20px"><div class="uni-top"><div class="rank">${i+1}</div><div class="uni-heading"><span class="pill">${phase.when}</span><h2 style="margin:10px 0">${phase.title}</h2><p class="muted">${phase.goal}</p></div><span class="pill">${done}/${ts.length} complete</span></div><div class="progress"><div style="width:${ts.length?100*done/ts.length:0}%"></div></div><details ${i===0?'open':''}><summary>Actions and dependencies</summary>${taskList(ts)}<p><b>Decision checkpoint:</b> ${phase.gate}</p>${link(phase.source,'Official reference')}</details></section>`}).join('')}<div class="notice">This plan is not automatic monitoring. Update tasks as you complete them, verify every deadline for your applicant category, and export a backup before moving devices.</div>`}
const timelineBeforeJourney=timeline;timeline=function(){return heading('Deadlines and work periods.','Early programme-specific dates matter. The full journey page contains the broader phase-by-phase plan.')+`<div class="deadline"><time>15 Feb 2027</time><div><h3>H-BRS winter 2027/28 · international degree</h3><p>Current specific admissions window is 15 November–15 February. Confirm pending-degree / APS evidence early.</p>${link('https://www.h-brs.de/en/inf/admission-application-master-autonomous-systems','Official admissions rule')}</div></div><div class="deadline"><time>1–31 May</time><div><h3>Fulda Data Science · non-EU foreign-degree window</h3><p>Winter-only. Confirm target year, A2 German, aptitude and degree-route requirements.</p>${link('https://www.hs-fulda.de/en/studyprogramme/data-science-msc','Official programme')}</div></div><div class="deadline"><time>15 Aug 2027</time><div><h3>H-BRS summer 2028 backup checkpoint</h3><p>Current summer international-degree window is 15 May–15 August of the preceding year.</p>${link('https://www.h-brs.de/en/inf/admission-application-master-autonomous-systems','Official admissions rule')}</div></div><p><a href="#journey">Open the complete journey and decision checkpoints</a></p><hr style="border:0;border-top:1px solid var(--line)">`+timelineBeforeJourney()};
document.addEventListener('change',e=>{if(['uni-type','uni-fees','uni-sort'].includes(e.target.id))uniResults();if(e.target.dataset.journeyPref){state.journeyPrefs[e.target.dataset.journeyPref]=e.target.value;save()}});
document.addEventListener('input',e=>{if(e.target.dataset.journeyPref){state.journeyPrefs[e.target.dataset.journeyPref]=e.target.value;save()}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-use-budget]');if(b){const u=universities.find(u=>u.id===b.dataset.useBudget);Object.assign(state.budget,{duration:u.months,monthly:u.monthly,semester:u.semester,tuition:u.tuition});save();location.hash='budget';toast('Programme assumptions copied. Confirm your actual duration and costs.')}});
const timelineWithReferences=timeline;
timeline=function(){return timelineWithReferences().replace(heading('Your timeline.','Published dates and personal targets are labelled separately. No automatic reminders are active.'),'')};
const overviewWithBothTypes=overview;
overview=function(){return overviewWithBothTypes().replace('Compare tuition-free programmes','Compare research and applied programmes')};
const budgetBeforeFamily=budgetResults;
budgetResults=function(){budgetBeforeFamily();const cap=Number(state.journeyPrefs.family.replaceAll(',',''));if(!Number.isFinite(cap)||cap<0)return;const b=state.budget,r=b.rate,terms=Math.ceil(b.duration/6),total=159500+770*r+b.duration*b.monthly*r+terms*(b.semester+b.tuition)*r+b.emergency,grant=Math.min(b.duration,b.awardMonths)*b.scholarship*r,gap=Math.max(0,total-grant-b.savings-b.loan);$('#budget-results').insertAdjacentHTML('beforeend',`<section class="notice"><h3>Your proposed family ceiling: ${money(cap)}</h3><p>Additional funding needed beyond this ceiling in the entered full-degree scenario: <b>${money(Math.max(0,gap-cap))}</b>. This compares the full study budget, not just departure cash. The family ceiling is not treated as money already received.</p><p>Strategy: prioritise substantial grants and affordable programmes. Confirm the award amount, duration and visa acceptance before committing. Borrowing remains undecided and is only counted if you explicitly enter secured repayable support.</p></section>`)};
const journeyBeforeBrief=journey;journey=function(){return journeyBeforeBrief().replace('<section class="panel">',`<section class="notice"><b>Your agreed direction:</b> industry employment in Data Science / AI; open to multi-country study if funding is strong; proposed family contribution up to ₹5 lakh. Loan preference remains undecided. Keep paid-fee programmes as comparisons until funding is demonstrated.</section><section class="panel">`)};
const compareBeforeExactFees=compare;compare=function(){return heading('Research and applied routes, side by side.','Compare institution type, city, degree length and formal requirements before paying.')+`<div class="notice">These are research records, not admission decisions. No transcript-based eligibility assessment has been completed. Institution type does not guarantee a job, practical experience or easier admission.</div><div class="panel table-wrap"><table class="comparison"><thead><tr><th>Programme</th>${universities.map(u=>`<th>${u.name}</th>`).join('')}</tr></thead><tbody>${[
['City & type',u=>`<b>${u.city}</b><p>${u.type}</p>`],
['Degree',u=>u.course],
['Duration',u=>u.durationLabel||u.months+' months'],
['Tuition / semester',u=>u.tuition?'€'+u.tuition+' ≈ '+money(u.tuition*state.budget.rate):'₹0 currently listed'],
['Programme-length estimate',u=>money(universityEstimate(u,u.months))+'<small>Living + tuition + semester fees; shortest route</small>'],
['Academic checks',u=>u.requirements],
['Intake & deadline',u=>u.intake+'<p>'+u.deadline+'</p>'],
['My assessment',u=>`<select data-fit="${u.id}" aria-label="Eligibility assessment for ${u.name}">${['Not assessed','Need clarification','Evidence collected','Requirements appear met','Does not fit'].map(v=>`<option ${state.comparison[u.id]?.status===v?'selected':''}>${v}</option>`).join('')}</select><textarea class="compare-note" data-fit-note="${u.id}" aria-label="Eligibility evidence for ${u.name}" placeholder="Coursework evidence and open questions…">${esc(state.comparison[u.id]?.note||'')}</textarea>`],
['Verify',u=>link(u.url,'Official programme')]
].map(([label,cell])=>`<tr><td>${label}</td>${universities.map(u=>`<td>${cell(u)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="muted">Indian credits require formal equivalence assessment. Confirm the actual 18/24-month route, missing coursework, fees and final-document deadlines.</p>`};
render();
